const sharedFaqPool = [
  { key: "edla-google", q: "What does Google EDLA certification actually guarantee?", a: "EDLA (Enterprise Device Licensing Agreement) certification means Google has verified the device for stable, ongoing access to the Google Play Store, Google Workspace, and Google Education Suite, plus regular over-the-air security updates. A board that just runs Android without EDLA certification can lose app-store access or stop receiving updates over time." },
  { key: "touch-simultaneous", q: "Does a higher touch-point count always mean a better writing experience?", a: "Not necessarily. Touch-point count measures how many contact points the sensor can track, but the number of people who can write clean, independent lines simultaneously is usually lower and separately documented by the manufacturer. Check the stated simultaneous-writer number, not just the raw touch-point spec, before assuming a 60-point board beats a 20-point one for group use." },
  { key: "ops-windows", q: "Do I need to buy anything extra to run Windows on a board with an OPS slot?", a: "Yes, in almost every case. An OPS (Open Pluggable Specification) slot is just an expansion bay, the actual Windows computer module that plugs into it is sold separately and can cost as much as a mid-range laptop. Confirm the OPS module price before assuming Windows compatibility is included in the board's sticker price." },
  { key: "mount-weight", q: "How much does a large interactive whiteboard weigh, and does that matter for installation?", a: "A 75-inch or larger panel commonly weighs 80 to 150+ pounds depending on the model. Confirm your wall has proper stud backing or use a VESA-compatible mobile stand rated for that weight, and consider professional installation at this size rather than a DIY wall mount." },
  { key: "cast-touchback", q: "Is wireless screen casting the same as wireless touch control?", a: "No, these are two separate features. Casting displays a connected phone, tablet, or laptop's screen on the board. Touch-back control additionally lets you operate that connected device's cursor and interface directly from the board's own touchscreen. Some boards support only casting, not touch-back, so check both separately." },
  { key: "warranty-support", q: "How long is the typical warranty on an interactive whiteboard?", a: "Warranty terms vary meaningfully across this category, from 18 months on some budget Android boards up to a 3-year standard warranty on ViewSonic's education-focused models, a 3-year onsite warranty on Promethean's ActivPanel line, and up to 4 years on some large-format 98-inch boards. Always check the specific product's warranty length rather than assuming a standard term across brands." },
  { key: "camera-mic-quality", q: "Do I need external cameras and microphones for video conferencing?", a: "It depends on the board. Several models in this category include built-in cameras (commonly 13-48MP) and microphone arrays purpose-built for Zoom, Teams, Meet, and Webex, while other boards, particularly HORION's line, explicitly support external cameras and mics you already own rather than including them, worth checking before assuming any board is conference-ready out of the box." },
  { key: "projector-vs-panel", q: "Is a projector-based interactive system cheaper than a flat panel?", a: "Often yes for the initial purchase, since a projector-based system reuses an existing wall or whiteboard surface rather than requiring an 80+ pound dedicated panel. The tradeoff is ongoing lamp replacement cost, sensitivity to ambient light, and periodic recalibration after the projector or sensor is moved, costs a flat panel doesn't carry." },
];

function fillFaq(specificFaq, count = 5) {
  const out = [...specificFaq];
  const specificText = specificFaq.map((f) => (f.q + f.a).toLowerCase()).join(" ");
  for (const item of sharedFaqPool) {
    if (out.length >= count) break;
    const topicWords = item.key.split("-");
    const alreadyCovered = topicWords.every((w) => specificText.includes(w));
    if (alreadyCovered) continue;
    out.push({ q: item.q, a: item.a });
  }
  return out;
}

function badge(i, total) {
  if (i === 0) return "Best Overall";
  if (i === total - 1 && total > 2) return "Budget Pick";
  return ["Runner-Up", "Also Great", "Strong Alternative", "Worth Considering", "Solid Option", "Another Pick"][Math.min(i - 1, 5)];
}

function pick(asin, badgeText) {
  const meta = lookup[asin];
  const info = P[asin];
  if (!meta || !info) return null;
  return {
    asin, badge: badgeText,
    name: info.name,
    price: meta.price || "Check price",
    rating: meta.rating,
    reviews: meta.reviewCount,
    imageUrl: meta.image,
    amazonUrl: `https://www.amazon.com/dp/${asin}?tag=theofficejournal-20`,
    description: info.p1 + "\n\n" + info.p2,
    specs: info.specs,
    pros: info.pros,
    cons: info.cons || [],
    bestFor: "",
  };
}

